// Package num provides shared number coercion helpers used by the template
// function namespaces. The semantics mirror the observed behaviour of the
// reference tool: strings are parsed leniently (base-prefix aware for ints),
// booleans coerce to 0/1, and floats truncate toward zero when converted to
// integers.
package num

import (
	"encoding/json"
	"strconv"
	"strings"
)

// IsFloat reports whether v should be treated as a floating-point value:
// either it is a float type, or it is a string (or json.Number) that only
// parses as a float (e.g. contains '.', 'e' or a float suffix).
func IsFloat(v any) bool {
	switch n := v.(type) {
	case float32, float64:
		return true
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return false
	case bool:
		return false
	case string:
		return stringIsFloat(n)
	case json.Number:
		return stringIsFloat(n.String())
	}
	return false
}

func stringIsFloat(s string) bool {
	s = strings.TrimSpace(s)
	if s == "" {
		return false
	}
	if _, err := strconv.ParseInt(s, 0, 64); err == nil {
		return false
	}
	_, err := strconv.ParseFloat(s, 64)
	return err == nil
}

// ToInt64 coerces v to an int64 using lenient parsing.
func ToInt64(v any) int64 {
	switch n := v.(type) {
	case int:
		return int64(n)
	case int8:
		return int64(n)
	case int16:
		return int64(n)
	case int32:
		return int64(n)
	case int64:
		return n
	case uint:
		return int64(n)
	case uint8:
		return int64(n)
	case uint16:
		return int64(n)
	case uint32:
		return int64(n)
	case uint64:
		return int64(n)
	case float32:
		return int64(n)
	case float64:
		return int64(n)
	case bool:
		if n {
			return 1
		}
		return 0
	case string:
		return stringToInt64(n)
	case json.Number:
		return stringToInt64(n.String())
	}
	return 0
}

func stringToInt64(s string) int64 {
	s = strings.TrimSpace(s)
	if i, err := strconv.ParseInt(s, 0, 64); err == nil {
		return i
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return int64(f)
	}
	return 0
}

// ToUint64 coerces v to a uint64 using lenient parsing.
func ToUint64(v any) uint64 {
	return uint64(ToInt64(v))
}

// ToFloat64 coerces v to a float64 using lenient parsing.
func ToFloat64(v any) float64 {
	switch n := v.(type) {
	case int:
		return float64(n)
	case int8:
		return float64(n)
	case int16:
		return float64(n)
	case int32:
		return float64(n)
	case int64:
		return float64(n)
	case uint:
		return float64(n)
	case uint8:
		return float64(n)
	case uint16:
		return float64(n)
	case uint32:
		return float64(n)
	case uint64:
		return float64(n)
	case float32:
		return float64(n)
	case float64:
		return n
	case bool:
		if n {
			return 1
		}
		return 0
	case string:
		return stringToFloat64(n)
	case json.Number:
		return stringToFloat64(n.String())
	}
	return 0
}

func stringToFloat64(s string) float64 {
	s = strings.TrimSpace(s)
	if i, err := strconv.ParseInt(s, 0, 64); err == nil {
		return float64(i)
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f
	}
	return 0
}

